class LRU {
  constructor(capacity) {
    this.capacity = capacity;
    this.cache = new Map();
  }

  get(key) {
    if (!this.cache.has(key)) {
      return undefined;
    }
    const value = this.cache.get(key);
    // Refresh recency by removing and re-adding
    this.cache.delete(key);
    this.cache.set(key, value);
    return value;
  }

  set(key, value) {
    // Remove if exists to update position
    if (this.cache.has(key)) {
      this.cache.delete(key);
    }
    // Add as most recently used
    this.cache.set(key, value);
    // Evict least recently used if over capacity
    if (this.cache.size > this.capacity) {
      const lruKey = this.cache.keys().next().value;
      this.cache.delete(lruKey);
    }
  }
}

module.exports.LRU = LRU;
```

This implementation uses a `Map` which maintains insertion order in JavaScript. Deleting and re-adding items moves them to the end, making them the most recently used. The least recently used item is always the first entry in the Map, so we evict it when capacity is exceeded.

