  const state = {}; // { [key]: { count, windowStart } }

  return {
    allow(key) {
      const now = Date.now();

      if (!state[key]) {
        state[key] = { count: 1, windowStart: now };
        return true;
      }

      const { count, windowStart } = state[key];

      // Check if current window has expired
      if (now >= windowStart + windowMs) {
        state[key] = { count: 1, windowStart: now };
        return true;
