        // Remove prefix and convert to lowercase config key
        const configKey = key.slice(envPrefix.length).toLowerCase();

        // Coerce the value
        let coercedValue = value;
        if (value === 'true') {
          coercedValue = true;
        } else if (value === 'false') {
          coercedValue = false;
        } else if (value !== '' && !isNaN(value)) {
          coercedValue = Number(value);
        }

        config[configKey] = coercedValue;
      }
    });
  }

  return config;
};
```

